/**
 * Level 2: at most one outlined secondary action per area (spec/02 §1.0, D143 (7)).
 * Other peer commands use SbTextAction (D144 (6)); dialog cancel is the §4.6 exception.
 * Secondary action: outlined, never filled. 48 dp, label in text. [busy] = its remote work runs (over 1 s, spec/02
 * §1.7): the turning 20 dp loader replaces [icon], the label stays, not clickable; TalkBack hears „Wird geladen …“.
 */
@Composable
fun SbSecondaryAction(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    enabled: Boolean = true,
    busy: Boolean = false,
) {
    SbSecondaryActionView(text, onClick, modifier, icon, enabled, busy, SebaroTheme.tokens.space.s6)   // the web's padding: 0 24px (spec/02 §1.2)
}

/**
 * [SbSecondaryAction] with its own [sides]: a board column's „Neue Karte in „<Spalte>““ keeps 8 dp, as the web's
 * .sb-board__add (D102 (36); review of the patterns lane, provisional, agent).
 */
@Composable
internal fun SbSecondaryActionView(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier,
    icon: ImageVector?,
    enabled: Boolean,
    busy: Boolean,
    sides: Dp,
    focusableWhenDisabled: Boolean = false,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val loading = sbMessages().loading
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val shape = t.shapes.control
    val label = if (enabled) c.text else c.textMuted
    Row(
        modifier
            .sbFocusRing(interaction, t.radius.control)
            .heightIn(min = t.size.controlMd)
            .clip(shape)
            .background(when { enabled && pressed -> c.pressedFill; enabled && hovered -> c.hoverFill; else -> c.bg }, shape)
            .border(t.borderWidth.control, if (enabled) c.borderStrong else c.border, shape)
            .then(if (busy) Modifier.semantics { stateDescription = loading } else Modifier)
            .clickable(interactionSource = interaction, indication = null, enabled = (enabled || focusableWhenDisabled) && !busy,
                role = Role.Button, onClick = { if (enabled) onClick() })
            .semantics { if (!enabled) disabled() }
            // 12 dp (space.s3) above and below the label, the room SbPrimaryAction keeps since CHECKS.md §47 (2026-11-01,
            // provisional, agent): a two-line label at font scale 2.0 had 2–3 dp to the outline; at font scale 1 the
            // 24 dp line and the inset make the 48 dp, so the height does not change
            .padding(horizontal = sides, vertical = t.space.s3),
        horizontalArrangement = Arrangement.spacedBy(t.spacing.inline, Alignment.CenterHorizontally),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (busy) SbSpinner(label)
        // D99 (1) (D102 lane patterns, 2026-10-25): words wrap between each other, centred; only a word wider than the
        // action is hyphenated, never broken before its closing quote as Text did („Weitermachen / “ at font scale 2.0)
        if (!busy && icon != null) {
            SbActionLabel(icon, text, label)
        } else {
            SbWrapText(text, SebaroTheme.typography.bodyStrong, label, center = true)
        }
    }
}

/**
 * An action's [icon] and [text], [color] both (D133, CHECKS.md §82): when a word would break beside the icon but for
 * the icon's room, the icon goes first; the word is measured as dark draws it without its letter spacing (D130), so
 * light and dark decide alike. A word too wide even alone is still hyphenated (D99 (1)).
 */
@Composable
internal fun SbActionLabel(icon: ImageVector, text: String, color: Color) {
    val t = SebaroTheme.tokens
    val style = SebaroTheme.typography.bodyStrong
    val measurer = rememberTextMeasurer()
    val widest = remember(text, style, measurer) {
        measurer.sbWidestWord(text, style.copy(fontWeight = sebaroTypography(dark = true).bodyStrong.fontWeight, letterSpacing = 0.em))
    }
    Layout(
        contents = listOf(
            { Icon(icon, contentDescription = null, tint = color, modifier = Modifier.size(t.size.iconLg)) },
            { SbWrapText(text, style, color, center = true) },
        ),
    ) { (i, w), c ->
        val iconRoom = t.size.iconLg.roundToPx() + t.spacing.inline.roundToPx()
        val shown = !c.hasBoundedWidth || widest + iconRoom <= c.maxWidth
        val ip = if (shown) i.map { it.measure(Constraints()) } else emptyList()
        val room = if (!c.hasBoundedWidth) Constraints.Infinity else if (shown) c.maxWidth - iconRoom else c.maxWidth
        val wp = w.map { it.measure(Constraints(maxWidth = room, maxHeight = c.maxHeight)) }
        val wordsWidth = wp.maxOfOrNull { it.width } ?: 0
        val height = maxOf(ip.maxOfOrNull { it.height } ?: 0, wp.maxOfOrNull { it.height } ?: 0).coerceIn(c.minHeight, c.maxHeight)
        val width = ((if (shown) iconRoom else 0) + wordsWidth).coerceIn(c.minWidth, c.maxWidth)
        layout(width, height) {
            ip.forEach { it.placeRelative(0, (height - it.height) / 2) }
            wp.forEach { it.placeRelative(if (shown) iconRoom else 0, (height - it.height) / 2) }
        }
    }
}

/**
 * Level 3 (D144 (6)): no frame; peer actions wrap in SbFlowRow (spec/02 §1.0).
 * Text action: a word in the link style (text colour, 2 dp link underline; D52) with a 48 dp target. [icon] (16 dp, in
 * textMuted, before the word, outside the underline; 2026-10-25 for a callout's „Ausblenden“, D102 (39)) is optional.
 * [enabled] = false (§14.36: „Ersetzen“ without a hit): the word in textMuted without the underline, no target,
 * TalkBack hears it as disabled (provisional, agent).
 */
@Composable
fun SbTextAction(text: String, onClick: () -> Unit, modifier: Modifier = Modifier, icon: ImageVector? = null, enabled: Boolean = true) {
    SbTextActionView(text, onClick, modifier, icon, enabled)
}

/** [SbTextAction]; [ringInside] for a place that clips it, as the toast whose frame lies over an outer ring (CHECKS.md §85). */
@Composable
internal fun SbTextActionView(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    enabled: Boolean = true,
    ringInside: Boolean = false,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    // a word that wraps at large text gets the underline under each line (spec/03 §15.3)
    var layout by remember { mutableStateOf<TextLayoutResult?>(null) }
    Box(
        modifier
            .then(if (ringInside) Modifier.sbFocusRingInset(interaction) else Modifier.sbFocusRing(interaction, t.radius.control))
            .heightIn(min = t.size.targetTouch)
            .widthIn(min = t.size.targetTouch)
            .clickable(interactionSource = interaction, indication = null, enabled = enabled, role = Role.Button, onClick = onClick)
            .padding(horizontal = t.space.s2),
        contentAlignment = Alignment.CenterStart,
    ) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
            if (icon != null) Icon(icon, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconSm))
            Text(
                text,
                style = SebaroTheme.typography.bodyStrong,
                color = when {
                    !enabled -> c.textMuted
                    pressed || hovered -> c.link
                    else -> c.text
                },
                modifier = if (enabled) Modifier.sbLinkUnderline { layout } else Modifier,
                onTextLayout = { layout = it },
            )
        }
    }
}

/**
 * Rounded rectangle whose top end corner is cut at 45° (D46: lime = next step, the cut = final). Only destructive
 * actions and a final step that deletes nothing (D102 (43)) use it. [radius] rounds the other three corners; [cut] is the length of each leg of the cut.
 */
@Immutable
class SbBevelShape(private val radius: Dp, private val cut: Dp) : Shape {
    override fun createOutline(size: Size, layoutDirection: LayoutDirection, density: Density): Outline {
        val w = size.width
        val h = size.height
        val r = with(density) { radius.toPx() }.coerceAtMost(size.minDimension / 2f)
        val k = with(density) { cut.toPx() }.coerceAtMost(size.minDimension / 2f)
        val q = r * 0.5523f // cubic handle of a quarter circle
        val rtl = layoutDirection == LayoutDirection.Rtl
        fun x(v: Float) = if (rtl) w - v else v
        val path = Path().apply {
            moveTo(x(r), 0f)
            lineTo(x(w - k), 0f)
            lineTo(x(w), k)
            lineTo(x(w), h - r)
            cubicTo(x(w), h - r + q, x(w - r + q), h, x(w - r), h)
            lineTo(x(r), h)
            cubicTo(x(r - q), h, x(0f), h - r + q, x(0f), h - r)
            lineTo(x(0f), r)
            cubicTo(x(0f), r - q, x(r - q), 0f, x(r), 0f)
            close()
        }
        return Outline.Generic(path)
    }
}

/**
 * Destructive action: the word (and icon) in danger inside a 1 dp danger outline with the 45° cut (D46), never
 * filled. [outlined] = false drops the outline (source compatibility only).
 */
@Composable
fun SbDangerAction(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    outlined: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val shape = remember(t.radius.control, t.x.dangerBevelSize) { SbBevelShape(t.radius.control, t.x.dangerBevelSize) }
    Row(
        modifier
            .sbFocusRing(interaction, shape)
            .heightIn(min = t.size.controlMd)
            .clip(shape)
            .background(if (pressed) c.pressedFill else if (hovered) c.hoverFill else Color.Transparent, shape)
            .then(if (outlined) Modifier.border(t.borderWidth.control, c.danger, shape) else Modifier)
            .clickable(interactionSource = interaction, indication = null, role = Role.Button, onClick = onClick)
            .padding(horizontal = if (outlined) t.spacing.insetControl else t.space.s0),
        horizontalArrangement = Arrangement.spacedBy(t.spacing.inline),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (icon != null) {
            SbActionLabel(icon, text, c.danger)
        } else {
            SbWrapText(text, SebaroTheme.typography.bodyStrong, c.danger, center = true)
        }
    }
}
